```sql
/* Находим медицинские роли, которые присутствуют во всех больницах (relational division) */
SELECT
    mr."rolename",
    mr."salary"
FROM "medicalroles" AS mr
WHERE mr."roleid" IN (
    /* Роли, встречающиеся в каждой больнице */
    SELECT hmr."roleid"
    FROM "hospitals_medical_roles" AS hmr
    GROUP BY hmr."roleid"
    HAVING COUNT(DISTINCT hmr."hospitalid") = (
        /* Общее количество больниц */
        SELECT COUNT(DISTINCT h."hospitalid")
        FROM "hospitals" AS h
    )
)
ORDER BY mr."rolename";
```

```sql
/* Находим финансовые роли, которые присутствуют одновременно во всех банках */
SELECT fr."rolename"
FROM "financial_roles" fr
JOIN "banks_financial_roles" bfr ON bfr."roleid" = fr."roleid"
GROUP BY fr."roleid", fr."rolename"
/* Роль должна встречаться у каждого банка из справочника */
HAVING COUNT(DISTINCT bfr."bankid") = (SELECT COUNT(*) FROM "banks");
```

